function validate([words, s]) {
  if (typeof s !== 'string' || s.length < 1 || s.length > 500) return 's needs 1 to 500 characters.';
  if (!/^[a-z]+$/.test(s)) return 's contains only lowercase letters.';
  if (!Array.isArray(words) || words.length > 50) return 'words holds at most 50 keywords.';
  for (const word of words) {
    if (typeof word !== 'string' || word.length < 1 || word.length > 10) return 'Each keyword has 1 to 10 characters.';
    if (!/^[a-z]+$/.test(word)) return 'Keywords contain only lowercase letters.';
  }
  return null;
}

