function boldWords(words, s) {
  const keys = new Set(words);
  const spans = [];
  for (let i = 0; i < s.length; i++)
    for (let j = i + 1; j <= Math.min(s.length, i + 10); j++)
      if (keys.has(s.slice(i, j))) spans.push([i, j]);
  spans.sort((a, b) => a[0] - b[0]);
  const merged = [];
  for (const [a, b] of spans) {
    if (merged.length && a <= merged[merged.length - 1][1]) merged[merged.length - 1][1] = Math.max(merged[merged.length - 1][1], b);
    else merged.push([a, b]);
  }
  let out = '', at = 0;
  for (const [a, b] of merged) {
    out += s.slice(at, a) + '<b>' + s.slice(a, b) + '</b>';
    at = b;
  }
  return out + s.slice(at);
}

