function generate(rand, size) {
  const large = size === 'large';
  const alphabet = 'abcdefghijklmnopqrstuvwxyz'.slice(0, 2 + Math.floor(rand() * (large ? 4 : 3)));
  const letter = () => alphabet[Math.floor(rand() * alphabet.length)];
  const n = large ? 500 - Math.floor(rand() * 10) : 1 + Math.floor(rand() * 12);
  const s = Array.from({ length: n }, letter).join('');
  const count = large ? 50 - Math.floor(rand() * 5) : Math.floor(rand() * 5);
  const maxLen = large ? 10 : 3;
  const words = [];
  for (let k = 0; k < count; k++) {
    const len = 1 + Math.floor(rand() * Math.min(maxLen, large ? 10 : n));
    if (rand() < 0.5 && len <= n) {
      const at = Math.floor(rand() * (n - len + 1));
      words.push(s.slice(at, at + len));
    } else {
      words.push(Array.from({ length: len }, letter).join(''));
    }
  }
  return [words, s];
}
